<script setup lang="ts">
import ShareSettings from './modules/share-settings.vue';
import { h } from 'vue';
import { NButton, NImage } from 'naive-ui';
import{onMounted,reactive,ref}from'vue';import ImageUpload from '@/components/image-upload/index.vue';import CollapseCard from '@/components/custom/collapse-card/index.vue';import DragSortList from '@/components/custom/drag-sort-list/index.vue';import{mediaUrl}from'@/utils/service';import{deleteAdminTopic,deletePublishCatalog,fetchAdminTopics,fetchPublishColors,fetchPublishDividers,fetchPublishEmojis,fetchPublishGroups,fetchPublishHealth,fetchPublishRules,fetchPublishSettings,rebuildPublishFeed,saveAdminTopic,savePublishColor,savePublishDivider,savePublishEmoji,savePublishGroup,sortAdminTopics,updatePublishRule,updatePublishSettings}from'@/service/api';
defineOptions({name:'PublishSettings'});const loading=ref(false),rules=ref<Api.Publish.Rule[]>([]),topics=ref<Api.Publish.Topic[]>([]),groups=ref<Api.Publish.Group[]>([]),emojis=ref<Api.Publish.Emoji[]>([]),colors=ref<Api.Publish.Color[]>([]),dividers=ref<Api.Publish.Divider[]>([]),health=ref<Api.Publish.Health>();const settings=reactive<Api.Publish.Settings>({reviewRequired:true,allowDownload:{defaultValue:true,userEditable:true},downloadWatermark:{defaultValue:false,userEditable:true},original:{defaultValue:false,userEditable:true},featureFlags:{emoji:true,mention:true,color:true,divider:true,link:true,poll:true},pollMinOptions:2,pollMaxOptions:10,commentImageMax:3,commentDeleteCascade:false});const topicOpen=ref(false),emojiOpen=ref(false);const topic=reactive<Api.Publish.Topic>({name:'',description:'',coverUrl:'',status:1,recommended:false,hot:false,enabled:true,sortOrder:0,viewCount:0});const emoji=reactive<Api.Publish.Emoji>({groupId:0,name:'',imageUrl:'',sortOrder:0,enabled:true});const newGroup=reactive<Api.Publish.Group>({name:'',sortOrder:0,enabled:true}),newColor=reactive<Api.Publish.Color>({name:'',colorValue:'#202124',sortOrder:0,enabled:true}),newDivider=reactive<Api.Publish.Divider>({name:'',previewText:'────────',sortOrder:0,enabled:true});
const modeName=(m:string)=>({image:'图文',video:'视频',post:'帖子'}[m]||m);async function load(){loading.value=true;try{const [s,r,t,g,e,c,d,hh]=await Promise.all([fetchPublishSettings(),fetchPublishRules(),fetchAdminTopics(),fetchPublishGroups(),fetchPublishEmojis(),fetchPublishColors(),fetchPublishDividers(),fetchPublishHealth()]);if(s.data)Object.assign(settings,s.data);rules.value=r.data||[];topics.value=t.data||[];groups.value=g.data||[];emojis.value=e.data||[];colors.value=c.data||[];dividers.value=d.data||[];health.value=hh.data}finally{loading.value=false}}async function saveSettings(){const r=await updatePublishSettings(settings);if(!r.error)window.$message?.success('发布设置已保存')}async function saveRule(rule:Api.Publish.Rule){const r=await updatePublishRule(rule);if(!r.error)window.$message?.success(modeName(rule.mode)+'限制已保存')}async function rebuildFeed(){const r=await rebuildPublishFeed();if(!r.error)window.$message?.success('已重建 '+(r.data||0)+' 条发布 Feed')}function editTopic(row?:Api.Publish.Topic){Object.assign(topic,row||{id:undefined,name:'',description:'',coverUrl:'',status:1,recommended:false,hot:false,enabled:true,sortOrder:0,viewCount:0});topicOpen.value=true}async function submitTopic(){const r=await saveAdminTopic(topic);if(!r.error){topicOpen.value=false;await load()}}function editEmoji(row?:Api.Publish.Emoji){Object.assign(emoji,row||{id:undefined,groupId:groups.value[0]?.id||0,name:'',imageUrl:'',sortOrder:0,enabled:true});emojiOpen.value=true}async function submitEmoji(){const r=await savePublishEmoji(emoji);if(!r.error){emojiOpen.value=false;await load()}}async function addGroup(){if(!newGroup.name.trim())return;await savePublishGroup(newGroup);newGroup.name='';await load()}async function addColor(){if(!newColor.name.trim())return;await savePublishColor(newColor);newColor.name='';await load()}async function addDivider(){if(!newDivider.name.trim())return;await savePublishDivider(newDivider);newDivider.name='';await load()}async function remove(type:string,id?:number){if(!id)return;await deletePublishCatalog(type,id);await load()}function removeTopic(row:Api.Publish.Topic){const d=window.$dialog?.warning({title:'删除话题',content:'确定删除话题「'+row.name+'」吗？若已有帖子使用该话题，将同时解除关联，删除后不可恢复。',positiveText:'删除',negativeText:'取消',onPositiveClick:async()=>{d!.loading=true;const r=await deleteAdminTopic(row.id!);if(r.error){d!.loading=false;return false}await load()}})}async function saveTopicOrder(){const r=await sortAdminTopics(topics.value.map(t=>t.id!));if(!r.error){window.$message?.success('话题顺序已保存');await load()}}onMounted(load);
</script>

<template>
  <div>
    <NSpace vertical :size="16">
      <ShareSettings />
      <NCard title="发布总设置" :bordered="false"><NSpin :show="loading"><NForm label-placement="left" label-width="190"><NFormItem label="新帖子先审后发"><NSwitch v-model:value="settings.reviewRequired" /></NFormItem><NFormItem v-for="(policy,key) in {allowDownload:settings.allowDownload,downloadWatermark:settings.downloadWatermark,original:settings.original}" :key="key" :label="({allowDownload:'允许下载',downloadWatermark:'下载水印',original:'原创'} as any)[key]"><NSpace align="center"><span>默认</span><NSwitch v-model:value="policy.defaultValue" /><NCheckbox v-model:checked="policy.userEditable">允许用户修改</NCheckbox></NSpace></NFormItem><NFormItem label="帖子编辑器能力"><NCheckbox v-for="key in ['emoji','mention','color','divider','link','poll']" :key="key" v-model:checked="settings.featureFlags[key]">{{ ({emoji:'表情',mention:'@用户',color:'文字颜色',divider:'分割线',link:'链接',poll:'投票'} as any)[key] }}</NCheckbox></NFormItem><NFormItem label="投票选项数"><NInputNumber v-model:value="settings.pollMinOptions" :min="2" :max="10" /><span class="mx-8px">至</span><NInputNumber v-model:value="settings.pollMaxOptions" :min="2" :max="10" /></NFormItem><NButton type="primary" @click="saveSettings">保存总设置</NButton></NForm></NSpin></NCard>
      <NCard title="分模式发布限制" :bordered="false"><NGrid cols="1 900:3" :x-gap="16" :y-gap="16"><NGridItem v-for="rule in rules" :key="rule.mode"><NCard :title="modeName(rule.mode)" size="small"><NForm label-placement="left" label-width="115"><NFormItem label="标题字数"><NInputNumber v-model:value="rule.titleMin" :min="0" />—<NInputNumber v-model:value="rule.titleMax" :min="0" /></NFormItem><NFormItem label="正文字数"><NInputNumber v-model:value="rule.contentMin" :min="0" />—<NInputNumber v-model:value="rule.contentMax" :min="0" /></NFormItem><NFormItem label="最多图片"><NInputNumber v-model:value="rule.imageMax" :min="0" /></NFormItem><NFormItem label="最多视频"><NInputNumber v-model:value="rule.videoMax" :min="0" /></NFormItem><NFormItem label="媒体总数"><NInputNumber v-model:value="rule.totalMediaMax" :min="0" /></NFormItem><NFormItem label="视频MB（0不限）"><NInputNumber v-model:value="rule.maxVideoMb" :min="0" /></NFormItem><NButton type="primary" @click="saveRule(rule)">保存</NButton></NForm></NCard></NGridItem></NGrid></NCard>
      <NCard title="评论设置" :bordered="false"><NForm label-placement="left" label-width="220"><NFormItem label="每条评论最多图片"><NInputNumber v-model:value="settings.commentImageMax" :min="0" :max="9" /><span class="ml-12px opacity-60">0 表示关闭评论图片</span></NFormItem><NFormItem label="删除根评论时同时删除回复"><NSwitch v-model:value="settings.commentDeleteCascade" /><span class="ml-12px opacity-60">关闭时，有回复的根评论显示“评论已删除”占位</span></NFormItem><NButton type="primary" @click="saveSettings">保存评论设置</NButton></NForm></NCard>
      <CollapseCard title="话题与自定义话题审核"><template #extra><NSpace align="center" :size="12"><span class="text-12px opacity-50">拖动手柄调整顺序</span><NButton type="primary" @click="editTopic()">新增话题</NButton></NSpace></template><NSpin :show="loading"><DragSortList v-model="topics" @reorder="saveTopicOrder"><template #header="{item}"><NSpace align="center" :size="8" class="min-w-0"><NImage v-if="item.coverUrl" :src="mediaUrl(item.coverUrl)" width="24" height="24" object-fit="cover" preview-disabled class="flex-shrink-0" /><span class="font-medium truncate">{{ item.name }}</span><NTag size="small" :type="item.status===1?'success':item.status===2?'error':'warning'">{{ ['待审核','已通过','已拒绝'][item.status]||'未知' }}</NTag><NTag v-if="item.hot" size="small" type="error">热门</NTag><NTag v-if="item.recommended" size="small" type="info">推荐</NTag><NTag v-if="!item.enabled" size="small" type="warning">已停用</NTag><span v-if="item.description" class="text-13px opacity-50 truncate" :title="item.description">{{ item.description }}</span></NSpace></template><template #actions="{item}"><span class="text-13px opacity-60 whitespace-nowrap">浏览 {{ item.viewCount }}</span><NButton size="small" @click="editTopic(item)">编辑</NButton><NButton size="small" type="error" @click="removeTopic(item)">删除</NButton></template></DragSortList></NSpin></CollapseCard>
      <NCard title="帖子与评论共用图片表情" :bordered="false"><NSpace><NInput v-model:value="newGroup.name" placeholder="新分组名称" /><NButton @click="addGroup">新增分组</NButton><NButton type="primary" :disabled="!groups.length" @click="editEmoji()">新增表情</NButton></NSpace><NSpace class="mt-16px"><NTag v-for="g in groups" :key="g.id" closable @close="remove('group',g.id)">{{ g.name }}</NTag></NSpace><NDataTable class="mt-16px" :data="emojis" :columns="[{title:'名称',key:'name'},{title:'图片',key:'imageUrl',render:(r:any)=>r.imageUrl?h(NImage,{src:mediaUrl(r.imageUrl),width:36,height:36,objectFit:'cover',previewDisabled:true}):'—'},{title:'分组ID',key:'groupId'},{title:'操作',key:'op',render:(r:any)=>h('div',{},[h(NButton,{size:'small',onClick:()=>editEmoji(r)},()=> '编辑'),h(NButton,{size:'small',type:'error',class:'ml-8px',onClick:()=>remove('emoji',r.id)},()=> '删除')])}]" /></NCard>
      <NGrid cols="1 900:2" :x-gap="16"><NGridItem><NCard title="文字颜色" :bordered="false"><NSpace><NInput v-model:value="newColor.name" placeholder="名称" /><NColorPicker v-model:value="newColor.colorValue" :show-alpha="false" /><NButton @click="addColor">新增</NButton></NSpace><NSpace class="mt-16px"><NTag v-for="c in colors" :key="c.id" closable :color="{color:c.colorValue,textColor:'#fff',borderColor:c.colorValue}" @close="remove('color',c.id)">{{ c.name }}</NTag></NSpace></NCard></NGridItem><NGridItem><NCard title="分割线" :bordered="false"><NSpace><NInput v-model:value="newDivider.name" placeholder="名称" /><NInput v-model:value="newDivider.previewText" placeholder="预览" /><NButton @click="addDivider">新增</NButton></NSpace><NSpace class="mt-16px"><NTag v-for="d in dividers" :key="d.id" closable @close="remove('divider',d.id)">{{ d.name }} {{ d.previewText }}</NTag></NSpace></NCard></NGridItem></NGrid>
      <NCard title="运行状态" :bordered="false"><template #header-extra><NButton @click="rebuildFeed">重建 Redis Feed</NButton></template><NDescriptions v-if="health" bordered :column="1"><NDescriptionsItem label="Redis"><NTag :type="health.redis.available?'success':'error'">{{ health.redis.message }}</NTag></NDescriptionsItem><NDescriptionsItem label="FFmpeg"><NTag :type="health.ffmpeg.available?'success':'error'">{{ health.ffmpeg.message }}</NTag><div>{{ health.ffmpeg.ffmpegPath||'未配置 FFMPEG_PATH' }}</div></NDescriptionsItem></NDescriptions></NCard>
    </NSpace>
    <NModal v-model:show="topicOpen" preset="card" title="话题" class="w-640px max-w-95vw"><NForm label-placement="left" label-width="90"><NFormItem label="名称"><NInput v-model:value="topic.name" maxlength="50" /></NFormItem><NFormItem label="说明"><NInput v-model:value="topic.description" type="textarea" maxlength="255" /></NFormItem><NFormItem label="封面"><ImageUpload v-model="topic.coverUrl" /></NFormItem><NFormItem label="审核"><NSelect v-model:value="topic.status" :options="[{label:'待审核',value:0},{label:'通过',value:1},{label:'拒绝',value:2}]" /></NFormItem><NFormItem label="展示"><NCheckbox v-model:checked="topic.enabled">启用</NCheckbox><NCheckbox v-model:checked="topic.hot">热门</NCheckbox><NCheckbox v-model:checked="topic.recommended">推荐</NCheckbox></NFormItem><NFormItem label="排序"><NInputNumber v-model:value="topic.sortOrder" /></NFormItem></NForm><template #footer><NSpace justify="end"><NButton @click="topicOpen=false">取消</NButton><NButton type="primary" @click="submitTopic">保存</NButton></NSpace></template></NModal>
    <NModal v-model:show="emojiOpen" preset="card" title="图片表情" class="w-560px max-w-95vw"><NForm label-placement="left" label-width="90"><NFormItem label="分组"><NSelect v-model:value="emoji.groupId" :options="groups.map(g=>({label:g.name,value:g.id}))" /></NFormItem><NFormItem label="名称"><NInput v-model:value="emoji.name" /></NFormItem><NFormItem label="图片"><ImageUpload v-model="emoji.imageUrl" /></NFormItem><NFormItem label="启用"><NSwitch v-model:value="emoji.enabled" /></NFormItem></NForm><template #footer><NSpace justify="end"><NButton @click="emojiOpen=false">取消</NButton><NButton type="primary" @click="submitEmoji">保存</NButton></NSpace></template></NModal>
  </div>
</template>
